#!/usr/bin/env python3
from pathlib import Path
import base64, gzip, subprocess, tempfile

PAYLOAD = ""

root = Path("FushERP_Mobile_Phase5")
if not root.is_dir():
    raise SystemExit("FushERP_Mobile_Phase5 source root not found")
raw = gzip.decompress(base64.b64decode(PAYLOAD))
with tempfile.NamedTemporaryFile(prefix="phase1459-", suffix=".diff", delete=False) as tmp:
    tmp.write(raw)
    diff_path = tmp.name
subprocess.run(["patch", "-p1", "--forward", "--batch", "-i", diff_path], cwd=root, check=True)
print("Phase 14.5.9 transfer reversal patch applied")
